// Test-only producer of an MSVC q4::Ring in a freshly spawned own child session.
// No audio activation, foreign process access, hooks, drivers or deployment.
#include "capture_reader_api.h"
#include "../../spatial-object-spike/resident/quantum_v4_protocol.h"
#include <nlohmann/json.hpp>
#include <filesystem>
#include <fstream>
#include <vector>
#include <map>
#include <iostream>
namespace fs=std::filesystem;using Json=nlohmann::json;
static void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
struct Handle {HANDLE h{};explicit Handle(HANDLE p=nullptr):h(p){}~Handle(){if(h&&h!=INVALID_HANDLE_VALUE)CloseHandle(h);}Handle(const Handle&)=delete;};
static LONG64 read(volatile LONG64& n){return InterlockedCompareExchange64(&n,0,0);}
static uint64_t born(HANDLE p){FILETIME a,b,c,d;check(GetProcessTimes(p,&a,&b,&c,&d)!=0,"own process identity");return uint64_t(a.dwHighDateTime)<<32|a.dwLowDateTime;}
static void save(const fs::path& p,const Json& j){std::ofstream f(p);f<<j.dump(2)<<'\n';check(bool(f),"fixture audit file");}
static std::wstring quote(const std::wstring& s){check(s.find(L'"')==std::wstring::npos,"own paths do not contain quotes");return L"\""+s+L"\"";}
struct Item {q4::Header h{};std::vector<float> pcm;};
int wmain(int argc,wchar_t** argv){try{
    check(argc==8||argc==9,"Usage: FIXTURE BROKER ADAPTER STREAM_DLL CAPTURE_DIR NEW_OUT REPEATS PACED [MODE]");auto broker=fs::absolute(argv[1]),adapter=fs::absolute(argv[2]),dll=fs::absolute(argv[3]),capture=fs::absolute(argv[4]),out=fs::absolute(argv[5]);unsigned repeats=std::stoul(argv[6]);bool paced=std::stoul(argv[7])!=0;std::wstring mode=argc==9?argv[8]:L"normal";check(mode==L"normal"||mode==L"idle"||mode==L"owner-exit"||mode==L"header-version"||mode==L"bad-owner"||mode==L"loss"||mode==L"sequence"||mode==L"missing-close"||mode==L"selected-none"||mode==L"self-excluded","fixture mode");check(repeats>=1&&repeats<=20&&(!paced||repeats==1),"bounded own fixture repetition");check(!fs::exists(out)&&fs::create_directories(out),"fresh fixture output");
    std::vector<Item> items;std::vector<fs::path> files;files.push_back(capture/L"global-objects.bin");for(unsigned n=1;;++n){wchar_t name[64];swprintf_s(name,L"global-objects-%04u.bin",n);if(!fs::exists(capture/name))break;files.push_back(capture/name);}
    uint64_t maxDomain=0;for(auto& path:files){std::ifstream f(path,std::ios::binary);check(bool(f),"frozen recording file");while(f.peek()!=EOF){Item item;f.read(reinterpret_cast<char*>(&item.h),sizeof(item.h));check(bool(f)&&item.h.version==4&&item.h.audio.frames<=kSamples&&item.h.audio.sequence==items.size(),"frozen event identity");item.pcm.resize(item.h.audio.frames);f.read(reinterpret_cast<char*>(item.pcm.data()),item.pcm.size()*4);check(bool(f),"frozen PCM bytes");if(item.h.domain>maxDomain)maxDomain=item.h.domain;items.push_back(std::move(item));check(items.size()<50000,"bounded fixture input");}}
    check(!items.empty()&&maxDomain==2,"two-domain frozen source");LARGE_INTEGER hz{};QueryPerformanceFrequency(&hz);auto qpcSpan=items.back().h.audio.qpc-items.front().h.audio.qpc+hz.QuadPart;
    SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};Handle map(CreateFileMappingW(INVALID_HANDLE_VALUE,&sa,PAGE_READWRITE,0,sizeof(q4::Ring),nullptr)),ready(CreateEventW(&sa,TRUE,FALSE,nullptr));HANDLE ownerRaw{};check(map.h&&ready.h&&DuplicateHandle(GetCurrentProcess(),GetCurrentProcess(),GetCurrentProcess(),&ownerRaw,SYNCHRONIZE|PROCESS_QUERY_LIMITED_INFORMATION,TRUE,0),"own fixture handles");Handle owner(ownerRaw);auto q=static_cast<q4::Ring*>(MapViewOfFile(map.h,FILE_MAP_ALL_ACCESS,0,0,sizeof(q4::Ring)));check(q!=nullptr,"own MSVC ring mapping");struct Unmap {void* p;~Unmap(){UnmapViewOfFile(p);}} unmap{q};memset(q,0,sizeof(*q));q->magic=kMagic;q->version=4;q->enginePid=GetCurrentProcessId();q->qpcFrequency=hz.QuadPart;q->status=1;
    auto number=[](HANDLE h){return std::to_wstring(reinterpret_cast<uintptr_t>(h));};auto childOut=out/L"broker";std::wstring command=quote(broker.wstring())+L" --capture-child "+quote(adapter.wstring())+L" "+quote(dll.wstring())+L" "+number(map.h)+L" "+number(owner.h)+L" "+number(ready.h)+L" "+std::to_wstring(GetCurrentProcessId())+L" "+std::to_wstring(born(GetCurrentProcess())+(mode==L"bad-owner"?1:0))+L" "+quote(childOut.wstring())+L" "+(paced?L"1":L"0")+L" "+mode+L" "+std::to_wstring(items.front().h.encoder);
    SIZE_T size{};InitializeProcThreadAttributeList(nullptr,1,0,&size);std::vector<BYTE> memory(size);auto attrs=reinterpret_cast<LPPROC_THREAD_ATTRIBUTE_LIST>(memory.data());check(InitializeProcThreadAttributeList(attrs,1,0,&size)!=0,"own attributes");HANDLE handles[]{map.h,owner.h,ready.h};check(UpdateProcThreadAttribute(attrs,0,PROC_THREAD_ATTRIBUTE_HANDLE_LIST,handles,sizeof(handles),nullptr,nullptr)!=0,"explicit three handles");STARTUPINFOEXW si{};si.StartupInfo.cb=sizeof(si);si.lpAttributeList=attrs;PROCESS_INFORMATION pi{};BOOL launched=CreateProcessW(broker.c_str(),command.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW|EXTENDED_STARTUPINFO_PRESENT,nullptr,nullptr,&si.StartupInfo,&pi);DeleteProcThreadAttributeList(attrs);check(launched!=FALSE,"spawn own GCC broker");Handle process(pi.hProcess),thread(pi.hThread);q->collectorPid=pi.dwProcessId;
    if(mode==L"header-version")q->version=3;
    save(out/L"launch.json",{{"producer_pid",GetCurrentProcessId()},{"consumer_pid",pi.dwProcessId},{"consumer_creation_time",born(process.h)},{"inherited_handles",3},{"source_events",items.size()},{"repeats",repeats},{"ring_slots",kSlots},{"ring_bytes",sizeof(q4::Ring)},{"capture_args_bytes",sizeof(spatial_capture::Args)},{"capture_event_bytes",sizeof(spatial_capture::Event)},{"own_fixture_only",true},{"audiodg_accessed",false}});SetEvent(ready.h);
    if(mode==L"owner-exit"){save(out/L"intentional-exit.json",{{"intentional_own_fixture_exit",true},{"code",23}});ExitProcess(23);}
    if(mode==L"idle"){auto until=GetTickCount64()+3000;while(read(q->heartbeat)==0&&GetTickCount64()<until&&WaitForSingleObject(process.h,0)==WAIT_TIMEOUT)Sleep(1);auto before=read(q->heartbeat);Sleep(150);auto after=read(q->heartbeat);save(out/L"idle-heartbeat.json",{{"before",before},{"after",after},{"read",read(q->read)},{"write",read(q->write)}});check(before>0&&after>before&&read(q->read)==0&&read(q->write)==0,"idle reader maintains capture heartbeat without inventing frames");}
    auto deadline=GetTickCount64()+25000;uint64_t sequence=0;bool okay=true;
    for(unsigned repeat=0;repeat<repeats&&okay;++repeat)for(auto& item:items){if(mode==L"missing-close"&&item.h.kind==q4::DomainEnd)continue;while(read(q->write)-read(q->read)>=kSlots&&GetTickCount64()<deadline&&WaitForSingleObject(process.h,0)==WAIT_TIMEOUT)Sleep(1);if(GetTickCount64()>=deadline||WaitForSingleObject(process.h,0)!=WAIT_TIMEOUT){okay=false;break;}auto& slot=q->slots[sequence%kSlots];slot.header=item.h;slot.header.audio.sequence=sequence+(mode==L"sequence"&&sequence==100?1:0);if(mode==L"loss"&&sequence==100)slot.header.lossEpoch=1;slot.header.domain+=repeat*maxDomain;slot.header.audio.qpc+=repeat*qpcSpan;if(!item.pcm.empty())memcpy(slot.pcm,item.pcm.data(),item.pcm.size()*4);InterlockedExchange64(&q->write,++sequence);}
    InterlockedExchange(&q->status,okay?2:-1);bool exited=WaitForSingleObject(process.h,25000)==WAIT_OBJECT_0;DWORD code=STILL_ACTIVE;if(exited)GetExitCodeProcess(process.h,&code);
    Json result={{"passed",okay&&exited&&code==0&&read(q->read)==read(q->write)},{"events_published",sequence},{"events_consumed",read(q->read)},{"input_ring_wraps",sequence/kSlots},{"consumer_exited",exited},{"consumer_exit",code},{"automatic_retry",false},{"forced_termination",false},{"audiodg_accessed",false}};save(out/L"proof.json",result);std::cout<<result.dump(2)<<'\n';return result["passed"].get<bool>()?0:2;
}catch(const std::exception& e){std::cerr<<"FAILED "<<e.what()<<'\n';return 3;}}
